'use strict';

const fs = require('node:fs');
const path = require('node:path');
const esbuild = require('esbuild');
const { writeFileAtomic } = require('./core/atomic-file');

const root = path.resolve(__dirname, '..');
const srcDir = path.join(root, 'src');
const entryFile = path.join(srcDir, 'dashboard', 'renderer-entry.js');
const outFile = path.join(srcDir, 'dashboard-renderer.js');
const devOutFile = path.join(srcDir, 'dashboard-renderer.dev.js');
const includedParts = new Set();

function readUtf8(file) {
  return fs.readFileSync(file, 'utf8').replace(/^\uFEFF/, '');
}

function rendererPartFile(name) {
  return path.join(srcDir, name);
}

function normalizePartName(item) {
  return String(item || '')
    .trim()
    .replace(/,$/, '')
    .replace(/^['"]/, '')
    .replace(/['"];?$/, '')
    .trim();
}

function parseIncludeList(raw) {
  const names = String(raw || '')
    .split(/\r?\n|,/)
    .map(normalizePartName)
    .filter((name) => name && !name.startsWith('//'));
  if (!names.length) throw new Error(`Could not parse renderer include list: ${raw}`);
  return names;
}

function partBlock(name, stack = []) {
  const cleanName = normalizePartName(name);
  const file = rendererPartFile(cleanName);
  if (!fs.existsSync(file)) throw new Error(`Missing renderer part: ${cleanName}`);
  if (stack.includes(cleanName)) throw new Error(`Circular renderer part include: ${[...stack, cleanName].join(' -> ')}`);
  includedParts.add(cleanName);
  const expanded = expandRendererIncludes(readUtf8(file), [...stack, cleanName]);
  return `\n/* ---- renderer part: ${cleanName} ---- */\n${expanded}\n/* ---- end renderer part: ${cleanName} ---- */\n`;
}

function expandRendererIncludes(entrySource, stack = []) {
  let source = String(entrySource || '');
  source = source.replace(
    /\/\*\s*@dashboard-include\s+([^*\r\n]+?)\s*\*\//g,
    (_, name) => partBlock(name, stack)
  );
  source = source.replace(
    /\/\*\s*@dashboard-include-list\s*([\s\S]*?)\*\//g,
    (_, raw) => parseIncludeList(raw).map((name) => partBlock(name, stack)).join('\n')
  );
  if (/\beval\s*\(/.test(source)) throw new Error('Renderer bundle source still contains eval(...)');
  if (/\breadRendererPart\b/.test(source) || /\brendererPartPath\b/.test(source)) {
    throw new Error('Renderer bundle source still contains the old runtime renderer part loader');
  }
  return source;
}

function stripBrowserCommonJsGuards(source) {
  return String(source || '')
    .replace(/if\s*\(\s*typeof module !== ['"]undefined['"]\s*&&\s*module\.exports\s*\)\s*module\.exports\s*=\s*api;?/g, '')
    .replace(/if\s*\(\s*typeof module !== ['"]undefined['"]\s*&&\s*module\.exports\s*\)\s*module\.exports\s*=\s*\{[^}]*\};?/g, '')
    .replace(/if\s*\(\s*typeof module !== ['"]undefined['"]\s*&&\s*module\.exports\s*\)\s*\{\s*module\.exports\s*=\s*\{[^}]*\};?\s*\}/g, '')
    .replace(/\?\s*globalThis\s*:\s*this/g, '? globalThis : globalThis');
}

function build(options = {}) {
  const dev = options.dev === true;
  includedParts.clear();
  const expanded = stripBrowserCommonJsGuards(expandRendererIncludes(readUtf8(entryFile)));
  const result = esbuild.transformSync(expanded, {
    loader: 'js',
    target: 'chrome120',
    ...(dev ? { format: 'esm' } : {}),
    legalComments: 'none',
    charset: 'utf8',
    sourcefile: 'dashboard/renderer-entry.expanded.js',
    sourcemap: dev ? 'external' : false,
    minifySyntax: !dev,
    minifyWhitespace: !dev,
    minifyIdentifiers: !dev,
  });
  if (/\beval\s*\(/.test(result.code)) throw new Error('Generated dashboard renderer still contains eval(...)');
  const manifest = [...includedParts].map((name) => ` * - ${name}`).join('\n');
  const target = dev ? devOutFile : outFile;
  const sourceMapComment = dev ? `\n//# sourceMappingURL=${path.basename(devOutFile)}.map` : '';
  writeFileAtomic(target, `/* Generated by src/build-dashboard-renderer.js. Do not edit directly. */\n/* Renderer parts:\n${manifest}\n */\n${result.code.trim()}\n/* End generated dashboard renderer bundle. */${sourceMapComment}\n`);
  if (dev) writeFileAtomic(`${devOutFile}.map`, result.map);
  const kb = (fs.statSync(target).size / 1024).toFixed(1);
  console.log(`dashboard renderer ${dev ? 'development ' : ''}bundle: ${path.relative(root, target)} ${kb}KB`);
}

if (require.main === module) build({ dev: process.argv.includes('--dev') });

module.exports = { expandRendererIncludes, stripBrowserCommonJsGuards, build };
